  function execution(){if(state.task?.stopped)return `<details class="execution"><summary>${icon('stop')}任务已停止<span class="grow"></span><span class="muted">可重新生成</span></summary><div class="steps caption">已中止本地演示计时器，没有调用模型或外部工具。</div></details>`;return `<details class="execution" ${state.busy?'open':''}><summary>${state.busy?'<span class="spinner"></span>':icon('check')}<span>${state.busy?'正在研究，整理证据与结论':'已完成研究'}</span><span class="grow"></span><span class="muted">${state.busy?'执行中':'4 个步骤'}</span>${icon('down','chevron')}</summary><div class="steps">${[['拆解研究问题','明确对比维度，建立资料清单','brain'],['检索与交叉核验','网页检索 / 网页读取 / 3 份演示资料','search'],['数据分析与可视化','数据分析师 / 表格和图表','chart'],['整理研究报告','HTML 分析报告及来源链接','file']].map(([a,b,c],i)=>`<div class="execution-step">${icon(state.busy&&i===3?'clock':'check',state.busy&&i===3?'warning':'success')}<div><span>${a}</span><p>${b}</p></div></div>`).join('')}</div></details>`;}
  function researchBody(){if(state.task?.stopped)return `<p class="soft">任务已停止。你可以调整问题后重新发送，或继续体验演示。</p>${button('重新生成','regenerate','refresh')}`;const sales=state.task?.kind==='sales';return `<h2>${sales?'第三季度销售数据分析':'AI 编程工具竞品调研'}</h2><p>已按${sales?'月度收入、产品结构与增长变化':'使用场景、核心能力、工作流与使用门槛'}整理演示报告。以下内容用于确认界面的阅读与交互效果。</p><p>${sales?'示例数据覆盖 7–9 月，整体收入呈上升趋势。可以在右侧交互图表中切换查看月度变化。':'对比工具时，应同时考虑上下文获取、工具执行、结果验证与交付能力，而不只比较模型的单轮回答。'}<button class="citation" data-action="sources" aria-label="查看来源 1">1</button><button class="citation" data-action="sources" aria-label="查看来源 2">2</button></p><ul><li><strong>${sales?'收入趋势':'核心能力'}</strong>：${sales?'月度收入从 12.8 万元增长至 18.6 万元。':'按代码理解、编辑、执行和验证拆分对比维度。'}</li><li><strong>${sales?'产品结构':'适用场景'}</strong>：${sales?'标准版贡献主要收入，专业版占比持续增加。':'区分日常补全、仓库级修改与长任务协作。'}</li><li><strong>${sales?'后续建议':'证据要求'}</strong>：${sales?'结合订单量、客单价和退款率进一步核验增长质量。':'为关键结论保留来源与核验日期。'}</li></ul><button type="button" class="file-artifact" data-action="open-report">${icon('file')}<span><strong>${sales?'第三季度销售分析':'AI 编程工具竞品调研'}.html</strong><small>HTML 报告 / 可交互图表 / 演示文件</small></span><span class="grow"></span><span class="text-link">打开预览</span>${icon('right')}</button><p class="caption">原型说明：上述数据及结论均为演示，不代表真实模型输出或调研事实。</p><div class="message-actions">${ib('copy','复制回答','copy-answer')}${ib('like','有帮助','feedback')}${ib('refresh','重新生成','regenerate')}</div>`;}
  function chat(){return `<section class="page"><div class="chat-layout"><div class="conversation"><header class="chat-header"><span class="chat-title">${E(taskTitle())}</span><div class="header-actions">${button('工作区','open-report','panel',state.workspace?'active':'')}${ib('star','收藏对话','favorite-chat')}${ib('settings','原型导航与显示','guide')}</div></header><div class="messages" id="message-scroll"><div class="message-column">${historyMessages()}<div class="user-message">${E(state.task?.query||taskTitle())}</div><article class="agent-message"><div class="agent-sign">${icon('spark')}<span>Research Agent</span><span class="grow"></span><span class="muted">${E(state.model)}</span></div>${execution()}<div id="answer-body">${state.busy?'<p class="soft">正在整理研究结果…</p>':researchBody()}</div></article></div></div><div class="chat-composer-area">${composer()}<p class="demo-note">交互原型，回答与执行步骤均为本地演示</p></div></div>${state.workspace?workspace():''}</div></section>`;}
  function workspace(){return `<aside class="workspace-pane" aria-label="右侧工作区" ${state.workspaceWidth?`style="width:${state.workspaceWidth}px"`:''}><button class="resize-handle" id="resize-handle" role="separator" aria-label="调整工作区宽度" aria-orientation="vertical" aria-valuemin="310" aria-valuemax="900" aria-valuenow="${state.workspaceWidth||480}"></button><div class="workspace-header">${icon('code')}<span>${state.workspaceTab==='sources'?'证据与来源':'index.html'}</span><span class="grow"></span>${ib('download','下载报告','download-report')}${ib('close','关闭工作区','close-workspace')}</div><div class="workspace-toolbar"><button class="${state.workspaceTab==='preview'?'active':''}" data-action="workspace-tab" data-tab="preview">预览</button><button class="${state.workspaceTab==='code'?'active':''}" data-action="workspace-tab" data-tab="code">代码</button><button class="${state.workspaceTab==='sources'?'active':''}" data-action="workspace-tab" data-tab="sources">来源 <span class="tag">3</span></button><span class="grow"></span><span class="muted">演示报告</span></div>${state.workspaceTab==='preview'?'<iframe class="report-frame" id="report-frame" title="HTML 分析报告预览" sandbox="allow-scripts"></iframe>':state.workspaceTab==='code'?`<pre class="code-view">${E(reportHTML())}</pre>`:`<div class="source-list">${['产品官方文档摘要','公开功能对照表','社区反馈整理'].map((s,i)=>`<div class="source-item"><span class="tag">${i+1}</span><strong>${s}</strong><p>示例证据，用于演示来源查看与交叉核验。</p><button class="text-link" data-action="read-source" data-index="${i}">查看原文摘要</button></div>`).join('')}<p class="demo-note">来源为虚构演示条目，不会访问外部网站。</p></div>`}</aside>`;}
  function reportHTML(){return `<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><style>*{box-sizing:border-box}body{margin:0;background:#f6f8f8;color:#203e49;font:13px/1.8 'Segoe UI','Microsoft YaHei UI',sans-serif}main{padding:32px 30px;max-width:1000px;margin:auto}small{color:#6d8791;font-size:10px}h1{font-size:26px;line-height:1.4;font-weight:550;letter-spacing:-1px;margin:14px 0}h2{font-size:15px;margin:26px 0 12px}p{color:#56727e}header{border-bottom:1px solid #d3e1e5;padding-bottom:22px}.stats{display:flex;gap:26px;margin:23px 0}.stats strong{display:block;font-size:24px;font-weight:500}.stats span{font-size:10px;color:#69818b}select{border:1px solid #ccdfe3;background:#fff;border-radius:6px;padding:5px 10px;color:#294f5e;font-size:11px}.bars{height:170px;display:flex;align-items:flex-end;gap:18px;padding:15px 18px 25px;border-bottom:1px solid #cadde1}.column{flex:1;background:#68a8b6;position:relative;border-radius:4px 4px 0 0;transition:height .25s}.column:nth-child(2){background:#3b7f93}.column:nth-child(3){background:#1e586f}.column span{position:absolute;bottom:-23px;left:0;right:0;text-align:center;font-size:10px;color:#63818d}.column i{position:absolute;top:-22px;left:0;right:0;text-align:center;font-style:normal;font-size:10px;color:#375f70}table{border-collapse:collapse;width:100%;font-size:11px}th,td{padding:10px 4px;text-align:left;border-bottom:1px solid #d5e2e5}th{font-weight:500;color:#62818f}.note{font-size:10px;padding:13px;background:#e6f0f2;border-radius:7px;margin-top:26px}footer{border-top:1px solid #d1e1e6;margin-top:28px;padding-top:15px;font-size:10px;color:#75909b}</style></head><body><main><header><small>Research Agent / 分析报告</small><h1>${E(state.task?.kind==='sales'?'第三季度销售数据分析':'AI 编程工具竞品调研')}</h1><p>从资料到判断：让结论、数据与证据保持关联。</p><small>演示报告　2026 年 10 月</small></header><div class="stats"><div><strong id="metric">47.6 万</strong><span id="metric-label">季度收入（示例）</span></div><div><strong>20.7%</strong><span>平均环比增长（示例）</span></div><div><strong>3</strong><span>分析维度</span></div></div><h2>月度变化 <select id="chart-type" aria-label="图表指标"><option value="revenue">收入</option><option value="orders">订单量</option></select></h2><div class="bars"><div class="column" style="height:61%"><i>12.8 万</i><span>7 月</span></div><div class="column" style="height:77%"><i>16.2 万</i><span>8 月</span></div><div class="column" style="height:89%"><i>18.6 万</i><span>9 月</span></div></div><h2>关键对比</h2><table><thead><tr><th>分析维度</th><th>关注内容</th><th>交付形式</th></tr></thead><tbody><tr><td>数据趋势</td><td>收入、订单与结构变化</td><td>统计表与图表</td></tr><tr><td>研究证据</td><td>来源与交叉核验</td><td>参考资料清单</td></tr><tr><td>后续行动</td><td>验证假设与补充数据</td><td>可执行建议</td></tr></tbody></table><div class="note">本页面为交互原型的虚构示例，可切换图表指标。未调用真实模型，数据不可用于业务决策。</div><footer>研究报告的内容保持独立样式；深海材质仅应用于工作区外壳。</footer></main><script>document.getElementById('chart-type').onchange=function(){const revenue=this.value==='revenue';document.querySelectorAll('.column').forEach((el,i)=>{el.style.height=(revenue?[61,77,89]:[69,81,86])[i]+'%';el.querySelector('i').textContent=(revenue?['12.8 万','16.2 万','18.6 万']:['640','810','930'])[i]});document.getElementById('metric').textContent=revenue?'47.6 万':'2,380';document.getElementById('metric-label').textContent=revenue?'季度收入（示例）':'季度订单（示例）';};<\/script></body></html>`;}
